package main

import (
	"strings"
	"testing"
)

func TestMethodRules(t *testing.T) {
	cfg := config{dir: "testdata/sample", specs: []spec{{"S", "registerS"}}, out: "x.go"}
	out, err := generate(cfg)
	if err != nil {
		t.Fatal(err)
	}
	src := string(out)
	if strings.Contains(src, "//go:build") {
		t.Errorf("generated file has a build constraint:\n%s", src)
	}
	for _, want := range []string{
		"// Code generated by rpcgen. DO NOT EDIT.",
		`u "net/url"`, `"time"`,
		`rpcName+".PtrArg"`, "rpcArg := new(time.Duration)", "rpcReply := new(u.URL)",
		`rpcName+".ValArg"`, "var rpcArg []string", "rpcReply := new(map[string]int)",
		`rpcName+".Grouped"`, "rpcArg := new(struct{})",
		"func registerS(rpcSrv *rpc.Server, rpcName string, rpcRcvr *S) error",
		`rpcSrv.HandleCall(rpcName+".PtrArg", func(rpcDec *gob.Decoder) (rpc.CallFunc, error) {`,
		"return func() (any, error) {",
	} {
		if !strings.Contains(src, want) {
			t.Errorf("generated file lacks %q", want)
		}
	}
	for _, skip := range []string{"unexported", "ThreeArgs", "NonPtrReply", "NoError", "TwoResults", "HiddenArg", "HiddenReply", "Variadic"} {
		if strings.Contains(src, `".`+skip+`"`) {
			t.Errorf("generated file registers %s, which net/rpc would not", skip)
		}
	}
}

func TestTargetsMustAgree(t *testing.T) {
	for _, tc := range []struct{ dir, typ, want string }{
		{"testdata/mismatch", "M", "JSOnly only on tinygo js/wasm"},
		{"testdata/notiny", "N", "NativeOnly only on linux/amd64"},
	} {
		_, err := generate(config{dir: tc.dir, specs: []spec{{tc.typ, "register"}}, out: "a.go"})
		if err == nil || !strings.Contains(err.Error(), tc.want) {
			t.Errorf("%s: want %q, got %v", tc.dir, tc.want, err)
		}
	}
}

func TestEmbeddedFieldRejected(t *testing.T) {
	_, err := generate(config{dir: "testdata/embedded", specs: []spec{{"E", "registerE"}}, out: "a.go"})
	if err == nil || !strings.Contains(err.Error(), "embeds a field") {
		t.Fatalf("want an embedded field error, got %v", err)
	}
}
